window.bookSummaryJSON = "<p><i>The First Days: As the World Dies</i> introduced Jenni and Katie and their harrowing journey to the makeshift fort in the Texas Hill Country. But theirs is not the only tale to be told. </p> <p>In <i>The Untold Tales</i> omnibus, experience 10 terrifying tales of those who are forced to face the unrelenting and hungry walking dead as the world dies.</p>"; 
